window.HOEREN_TESTS[51] = {"id":"im-schwimmbad-und-sauna","name":"Im Schwimmbad und Sauna","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Gäste: Unser Schwimmbad hat ab Montag neue Öffnungszeiten. Statt 6 bis 22 Uhr nun 7 bis 23 Uhr, wir öffnen also um 7 Uhr, nicht um 6 Uhr. Sonntags 9 bis 20 Uhr, keine Änderung. Der Sauna-Bereich nur ab 18 Jahren, wie immer. Das Kinderbecken bleibt bis 21 Uhr offen. Vielen Dank und viel Spaß im Wasser!","gender":"f","q":"Wann öffnet das Schwimmbad jetzt?","opts":["9 Uhr.","6 Uhr.","7 Uhr."],"correct":2},{"transcript":"Hallo Tom, hier ist Markus. Gehst du heute schwimmen? Ich will nicht nur schwimmen und nicht nur in die Sauna, ich will beides, erst Bahnen und dann die neue Sauna. Die ist sehr modern, wir kannten sie noch nicht. Treffen um 16 Uhr beim Eingang. Der Sauna-Eintritt kostet extra, aber es lohnt sich. Ruf zurück, ja oder nein.","gender":"m","q":"Was möchte Markus tun?","opts":["Schwimmen und Sauna.","Nur schwimmen.","Nur Sauna."],"correct":0},{"transcript":"Achtung Besucher: Heute ist Kurs-Tag im Schwimmbad. Zwischen 14 und 16 Uhr sind die Schwimm-Bahnen 1 bis 3 für Kurse reserviert, also nicht frei. Bahn 4 und 5 sind frei für normale Schwimmer. Alle Bahnen frei gibt es heute Nachmittag nicht. Wer einen Kurs machen will, bitte an der Kasse anmelden. Danke für Ihr Verständnis!","gender":"m","q":"Welche Bahnen sind frei?","opts":["Bahn 4 und 5.","Bahn 1-3.","Alle Bahnen."],"correct":0},{"transcript":"Hi Anna, hier ist Lisa. Ich gehe heute zum Aqua-Fitness. Hast du Lust mitzukommen? Der Kurs beginnt um 18 Uhr und dauert eine Stunde. Er kostet nicht 10 Euro und nicht 20 Euro, sondern 15 Euro Eintritt, inklusive Pool danach. Das macht Spaß und ist gut für den Rücken. Bring Badeanzug und Handtuch mit. Ruf bitte zurück!","gender":"f","q":"Was kostet der Kurs?","opts":["10 Euro.","15 Euro.","20 Euro."],"correct":1},{"transcript":"Liebe Sauna-Gäste: In der finnischen Sauna ist heute Aufguss um 19 Uhr 30, nicht um 19 Uhr. Eukalyptus-Duft, sehr erfrischend. Vorher 20 Minuten Pause empfohlen. Wer Probleme mit den Atemwegen hat, bitte nicht teilnehmen. Im Bio-Sauna ist der Aufguss um 20 Uhr. Wir wünschen euch eine schöne Entspannung!","gender":"f","q":"Wann ist Aufguss in der finnischen Sauna?","opts":["20 Uhr.","19 Uhr.","19 Uhr 30."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Was machen sie an welchem Tag am liebsten? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Das Schwimmbad hat diese Woche bis abends lange auf."},{"speaker":"Lisa","gender":"f","text":"Schön, dass du den Plan machst. Ich wollte schon lange wieder ins Wasser."},{"speaker":"Lukas","gender":"m","text":"Ich gehe montags besonders gern in die Sauna. Die Wärme nach der Arbeit tut gut."},{"speaker":"Lisa","gender":"f","text":"Ich schwimme dienstags früh Bahnen. Zehn Stück machen mich vor der Arbeit wach."},{"speaker":"Lukas","gender":"m","text":"Kommt jemand mit ins Kinderbecken?"},{"speaker":"Lisa","gender":"f","text":"Nein. Das Kinderbecken brauchen wir nicht."},{"speaker":"Lukas","gender":"m","text":"Tom will am Mittwoch etwas Lautes. Er fährt dann die Wasserrutsche."},{"speaker":"Lisa","gender":"f","text":"Seine Freunde warten schon unten und klatschen laut."},{"speaker":"Lukas","gender":"m","text":"Sara springt am Donnerstag vom Turm. Die Höhe macht ihr gar nichts."},{"speaker":"Lisa","gender":"f","text":"Ich schaue nur von unten zu und filme den Sprung."},{"speaker":"Lukas","gender":"m","text":"Macht jemand am Abend Aqua-Fitness mit?"},{"speaker":"Lisa","gender":"f","text":"Nein. Aqua-Fitness machen wir nicht. Dafür sind wir zu müde."},{"speaker":"Lukas","gender":"m","text":"Tim bleibt am Freitag lange im Whirlpool. Die warmen Blasen helfen seinem Rücken."},{"speaker":"Lisa","gender":"f","text":"Das ist ruhig nach einer vollen Woche im Wasser."},{"speaker":"Lukas","gender":"m","text":"Dann hänge ich den Plan an den Kühlschrank."},{"speaker":"Lisa","gender":"f","text":"Ich bringe die großen Handtücher mit. Wir starten dann in der Wärme."}],"options":[{"letter":"a","text":"Vom Turm springen"},{"letter":"b","text":"Whirlpool"},{"letter":"c","text":"Aqua-Fitness"},{"letter":"d","text":"Massage"},{"letter":"e","text":"Bahnen schwimmen"},{"letter":"f","text":"Wasserrutsche"},{"letter":"g","text":"Kinderbecken"},{"letter":"h","text":"Dampfbad"},{"letter":"i","text":"Sauna"}],"items":[{"person":"Montag","correct":"i"},{"person":"Dienstag","correct":"e"},{"person":"Mittwoch","correct":"f"},{"person":"Donnerstag","correct":"a"},{"person":"Freitag","correct":"b"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, ich möchte bitte eintreten. Was kostet das heute?"},{"speaker":"Kassiererin","gender":"f","text":"Schwimmbad oder Sauna? Schwimmbad allein 8 Euro, Sauna allein 15 Euro."},{"speaker":"Kundin","gender":"f","text":"Ich möchte beides, erst schwimmen und dann in die Sauna. Gibt es eine Kombi?"},{"speaker":"Kassiererin","gender":"f","text":"Ja, die Kombi kostet 20 Euro. 8 Euro nur fürs Bad, 15 nur für die Sauna, zusammen 20."},{"speaker":"Kundin","gender":"f","text":"Okay, dann die Kombi für 20 Euro. Hier ist das Geld, danke!"}],"q":"Was kostet die Kombi?","opts":["8 Euro.","15 Euro.","20 Euro."],"correct":2},{"lines":[{"speaker":"Vater","gender":"m","text":"Entschuldigung, wo ist das Kinderbecken bitte? Meine Tochter ist erst drei."},{"speaker":"Bademeister","gender":"m","text":"Hinten rechts, hinter dem Schwimmer-Becken. Dort ist es flach und sicher."},{"speaker":"Vater","gender":"m","text":"Wie tief ist das Wasser? 20 cm, 40 cm oder schon 1 Meter?"},{"speaker":"Bademeister","gender":"m","text":"40 cm, nicht 20 cm und nicht 1 Meter. Das ist sicher für Kleine, keine Sorge."},{"speaker":"Vater","gender":"m","text":"Gut, 40 cm. Dann gehen wir dorthin. Danke für die Info!"}],"q":"Wie tief ist das Kinderbecken?","opts":["20 cm.","40 cm.","1 Meter."],"correct":1},{"lines":[{"speaker":"Mutter","gender":"f","text":"Guten Tag, hat Klein-Sara einen Schwimm-Kurs bei Ihnen? Sie ist fünf und Anfängerin."},{"speaker":"Lehrerin","gender":"f","text":"Ja, Anfängerkurs gibt es am Mittwoch oder am Samstag. Sonntag haben wir keinen Kinderkurs."},{"speaker":"Mutter","gender":"f","text":"Mittwoch ist zu spät am Abend, da ist sie müde. Sonntag geht auch nicht. Samstag?"},{"speaker":"Lehrerin","gender":"f","text":"Dann Samstag um 10 Uhr. Mittwoch und Sonntag lassen wir weg, Samstag passt besser."},{"speaker":"Mutter","gender":"f","text":"Ja, Samstag um 10 ist gut. Ich trage Sara ein, danke!"}],"q":"Wann hat Sara den Kurs?","opts":["Samstag.","Mittwoch.","Sonntag."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, welche Sauna empfehlen Sie heute? Ich bin zum ersten Mal hier."},{"speaker":"Frau am Empfang","gender":"f","text":"Die finnische Sauna ist sehr heiß, das Dampfbad ist schwül. Die Bio-Sauna ist milder."},{"speaker":"Mann","gender":"m","text":"Ich bin Anfänger, finnisch klingt zu heiß und Dampfbad mag ich nicht. Was dann?"},{"speaker":"Frau am Empfang","gender":"f","text":"Dann die Bio-Sauna, 60 Grad, gut zum Start. Finnisch und Dampfbad später, wenn Sie wollen."},{"speaker":"Mann","gender":"m","text":"Gut, dann Bio-Sauna. Danke für den Tipp, das hilft mir wirklich!"}],"q":"Was wird empfohlen?","opts":["Finnische Sauna.","Bio-Sauna.","Dampfbad."],"correct":1},{"lines":[{"speaker":"Junge","gender":"m","text":"Papa, ich will auf die Rutsche! Der Turm sieht auch cool aus, darf ich?"},{"speaker":"Vater","gender":"m","text":"Auf den Turm darfst du nicht, der ist nur ab 1 Meter 40. Die Rutsche ab 1 Meter 20."},{"speaker":"Junge","gender":"m","text":"Ich bin 1 Meter 20, wirklich! Also darf ich rutschen, oder gar nicht rutschen?"},{"speaker":"Vater","gender":"m","text":"Lass mal messen, hier. Genau 1,20. Okay, du darfst auf die Rutsche, aber nicht auf den Turm."},{"speaker":"Junge","gender":"m","text":"Super, dann gehe ich auf die Rutsche. Danke Papa, bis gleich am Becken!"}],"q":"Was darf der Junge?","opts":["Auf die Rutsche.","Nicht rutschen.","Auf den Turm."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Klein, einer Bademeisterin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Klein, Sie arbeiten als Bademeisterin seit 15 Jahren. Was machen Sie genau?"},{"speaker":"Klein","gender":"f","text":"Hauptaufgabe ist die Sicherheit der Gäste. Aufpassen, dass niemand ertrinkt. Auch Kontrolle der Wasser-Qualität, Chlor messen, Hygiene. Erste Hilfe leisten, wenn nötig. Im Sommer viel zu tun, im Winter ruhiger."},{"speaker":"Reporter","gender":"m","text":"Müssen Sie oft jemanden retten?"},{"speaker":"Klein","gender":"f","text":"Echte Rettungen — etwa fünf pro Jahr. Aber kleine Hilfen oft: Kinder, die sich nicht trauen. Senioren mit Kreislauf-Problemen. Eltern, die nicht aufpassen. Pro Tag etwa drei Vorfälle, die wir lösen müssen."},{"speaker":"Reporter","gender":"m","text":"Wer kommt zum Schwimmen?"},{"speaker":"Klein","gender":"f","text":"Sehr gemischt. Morgens Senioren — die mögen Ruhe. Mittags Schulkinder mit Lehrer. Nachmittags Familien. Abends Sportler — Bahnen schwimmen, fit bleiben. Wochenenden voll, oft Warteschlangen."},{"speaker":"Reporter","gender":"m","text":"Was sind die häufigsten Probleme?"},{"speaker":"Klein","gender":"f","text":"Eltern, die nicht aufpassen und Handy gucken. Kinder gehen weg, suchen wir dann zusammen. Auch Streit — wer kommt in die Sauna, Plätze, sowas. Und der Wasserrutsche-Bereich — viele Verletzungen, weil Leute rennen."},{"speaker":"Reporter","gender":"m","text":"Schwimmen Sie selbst auch?"},{"speaker":"Klein","gender":"f","text":"Manchmal, ja. Aber nicht hier. Privat fahre ich an Seen — Natur ist schöner als Chlor-Wasser. Im Urlaub immer am Meer — Schwimmen ist mein Leben."}],"items":[{"q":"Sie hat etwa 50 echte Rettungen pro Jahr.","correct":"nein"},{"q":"Eine Aufgabe ist die Kontrolle der Wasser-Qualität.","correct":"ja"},{"q":"Eltern, die Handy gucken statt aufzupassen, sind ein Problem.","correct":"ja"},{"q":"Im Wasserrutschen-Bereich gibt es viele Verletzungen.","correct":"ja"},{"q":"Sie schwimmt privat im selben Schwimmbad.","correct":"nein"}]}]};
